func deserializeVolumeToSizeMap(d smithy.ShapeDeserializer, s *smithy.Schema, v *map[string]int64) error {
	*v = make(map[string]int64)
	var vv int64
	return smithy.ReadMap(d, s, func(k string) error {

		if err := d.ReadInt64(s.MapValue(), &vv); err != nil {
			return err
		}

		(*v)[k] = vv
		return nil
	})
}
